st.markdown("""
<style>
:root{
  --navy:#102a56;--blue:#2563eb;--purple:#7c3aed;--pink:#ec4899;
  --ink:#102a56;--muted:#667085;--bg1:#f8f3ff;--bg2:#eef7ff;--bg3:#fff1f7;
}
.stApp{background:linear-gradient(135deg,var(--bg1),var(--bg2) 48%,var(--bg3));}
.block-container{padding-top:1rem;max-width:1400px}
button[kind="secondary"]{border-radius:12px!important}
.fp-title{font-size:2.4rem;font-weight:900;color:var(--ink);margin:8px 0 4px}
.fp-sub{color:var(--muted);font-size:1.02rem;margin-bottom:18px}
.fp-section{font-size:1.65rem;font-weight:850;color:var(--ink);margin:22px 0 8px}
.fp-card{background:rgba(255,255,255,.92);border:1px solid #e5e7eb;border-radius:20px;padding:20px;box-shadow:0 8px 24px rgba(30,41,59,.08);height:100%;}
.fp-card h3{margin:5px 0 6px;color:var(--ink)}
.fp-card p{color:#475467}
.fp-chip{display:inline-block;padding:6px 10px;border-radius:999px;background:#eef2ff;color:#4338ca;font-weight:700;font-size:.82rem;margin:3px}
.fp-tree{background:white;border:1px solid #e6e8ec;border-radius:20px;padding:18px 20px;box-shadow:0 8px 22px rgba(30,41,59,.06)}
.fp-tree-line{font-size:1.05rem;font-weight:750;color:var(--ink);padding:9px 0;border-bottom:1px dashed #d8dee9}
.fp-tree-line:last-child{border-bottom:0}
.fp-note{background:linear-gradient(135deg,#eff6ff,#f5f3ff);border:1px solid #dbeafe;border-radius:18px;padding:14px 16px;color:#334155}
.ai-box{background:linear-gradient(135deg,#eef7ff,#faf5ff);border:1px solid #dbeafe;border-radius:22px;padding:18px}
.small-muted{color:#667085;font-size:.9rem}
.back-wrap{margin:0 0 12px 0;display:flex;align-items:center}
.back-wrap .stButton>button{background:linear-gradient(135deg,#102a56,#4f46e5)!important;color:#fff!important;border:0!important;border-radius:12px!important;min-height:46px!important;padding:0 20px!important;font-weight:800!important;box-shadow:0 7px 18px rgba(79,70,229,.24)!important}
.back-wrap .stButton>button:hover{transform:translateY(-1px);box-shadow:0 10px 22px rgba(79,70,229,.30)!important}
.hero-shell{position:relative;width:100%;overflow:hidden;border-radius:22px;box-shadow:0 10px 28px rgba(16,42,86,.12);background:white;line-height:0}
.hero-shell img{display:block;width:100%;height:auto}
.hero-hotspot{position:absolute;left:38.2%;top:43.7%;width:22.5%;height:8.2%;display:block;border-radius:999px;z-index:5;cursor:pointer;background:transparent;-webkit-tap-highlight-color:transparent}

/* FuturePath custom sidebar */
section[data-testid="stSidebar"]{
  background:linear-gradient(180deg,#07142d 0%,#0b1734 58%,#071229 100%) !important;
  border-right:1px solid rgba(255,255,255,.06);
}
section[data-testid="stSidebar"] > div:first-child{padding:.75rem .65rem .8rem .65rem}
section[data-testid="stSidebar"] [data-testid="stMarkdownContainer"] p,
section[data-testid="stSidebar"] [data-testid="stMarkdownContainer"] h1,
section[data-testid="stSidebar"] [data-testid="stMarkdownContainer"] h2,
section[data-testid="stSidebar"] [data-testid="stMarkdownContainer"] h3{color:#f8fbff !important}
.fp-side-brand{padding:8px 10px 20px}
.fp-side-brand .logo{font-size:1.65rem;font-weight:900;letter-spacing:-.6px;color:#fff}
.fp-side-brand .future{color:#fff}.fp-side-brand .path{color:#8b5cf6}
.fp-side-brand .tag{color:#9fb0d0;font-size:.78rem;margin-top:3px}
.fp-side-active{width:100%;box-sizing:border-box;padding:12px 14px;border-radius:16px;background:linear-gradient(100deg,#4f46e5,#7355e9 55%,#5266ee);color:#fff;font-weight:800;font-size:1rem;box-shadow:0 10px 25px rgba(91,76,224,.24);margin:5px 0}
section[data-testid="stSidebar"] button[kind="secondary"]{border:1px solid transparent !important;background:transparent !important;color:#fff !important;text-align:left !important;border-radius:14px !important;min-height:48px !important;font-size:1rem !important;font-weight:600 !important;box-shadow:none !important;margin:3px 0 !important}
section[data-testid="stSidebar"] button[kind="secondary"]:hover{background:rgba(113,83,232,.17) !important;border-color:rgba(126,101,239,.22) !important}
.fp-side-spacer{height:250px}
.fp-side-footer{color:#a9b9df;font-style:italic;font-size:.95rem;line-height:1.25;text-align:center;padding:8px 12px 16px}
@media(max-width:800px){.fp-side-spacer{height:90px}}

@media(max-width:900px){.fp-title{font-size:2rem}}

/* ============================================================
   Responsive layout: desktop + tablet + mobile
   ============================================================ */
html,body{overflow-x:hidden!important}
.stApp{min-width:0!important;overflow-x:hidden!important}
.block-container{width:100%!important;max-width:1400px!important;box-sizing:border-box!important}
[data-testid="stHorizontalBlock"]{width:100%!important;max-width:100%!important;box-sizing:border-box!important}
[data-testid="stColumn"]{min-width:0!important;box-sizing:border-box!important}
.fp-card{min-width:0!important;overflow-wrap:anywhere!important;word-break:break-word!important}
.fp-card h3,.fp-card p{overflow-wrap:anywhere!important}
.stButton>button,.stDownloadButton>button{width:100%!important;min-height:44px!important;white-space:normal!important;overflow-wrap:anywhere!important}
.stTextInput input,.stSelectbox div[data-baseweb="select"]{max-width:100%!important}

/* Make the FuturePath sidebar look like one deliberate custom panel. */
section[data-testid="stSidebar"]{box-sizing:border-box!important;width:265px!important;min-width:265px!important;max-width:265px!important;overflow-x:hidden!important}
section[data-testid="stSidebar"] > div:first-child{width:100%!important;box-sizing:border-box!important}
section[data-testid="stSidebar"] .block-container{padding-left:.7rem!important;padding-right:.7rem!important}
section[data-testid="stSidebar"] [data-testid="stVerticalBlock"]{max-width:100%!important}
.fp-side-brand{width:100%!important;box-sizing:border-box!important}
.fp-side-brand .logo{white-space:nowrap!important}
.fp-side-active{width:100%!important;box-sizing:border-box!important;white-space:normal!important}

/* Prevent accidental duplicate/native-looking light controls inside sidebar. */
section[data-testid="stSidebar"] .stSelectbox{display:none!important}
section[data-testid="stSidebar"] [data-testid="stSidebarNav"]{display:none!important}
section[data-testid="stSidebar"] header{background:transparent!important}

@media(max-width:1100px){
  .block-container{padding-left:.9rem!important;padding-right:.9rem!important}
  .fp-title{font-size:2.05rem}
  .fp-section{font-size:1.45rem}
  .hero-shell{border-radius:18px}
  section[data-testid="stSidebar"]{width:250px!important;min-width:250px!important;max-width:250px!important}
}

@media(max-width:700px){
  /* MOBILE: make the cinematic homepage a full-screen hero.
     Do NOT reset the image height back to auto here. */
  .block-container{
    width:100%!important;
    max-width:none!important;
    padding:.15rem 0 0!important;
    margin:0!important;
  }
  .hero-shell{
    position:relative!important;
    width:100vw!important;
    max-width:100vw!important;
    height:calc(100svh - 8px)!important;
    min-height:540px!important;
    max-height:none!important;
    margin-left:calc(50% - 50vw)!important;
    margin-right:calc(50% - 50vw)!important;
    border-radius:0!important;
    overflow:hidden!important;
    box-shadow:none!important;
    background:#07142d!important;
  }
  .hero-shell img{
    display:block!important;
    width:100%!important;
    height:100%!important;
    max-width:none!important;
    max-height:none!important;
    object-fit:cover!important;
    object-position:center 47%!important;
  }
  /* Large touch area around the Start Your Journey button in the artwork. */
  .hero-hotspot{
    left:16%!important;
    top:47%!important;
    width:68%!important;
    height:18%!important;
    display:block!important;
    z-index:20!important;
    cursor:pointer!important;
    touch-action:manipulation!important;
    -webkit-tap-highlight-color:transparent!important;
  }
  .fp-title{font-size:1.5rem!important;line-height:1.18!important}
  .fp-sub{font-size:.94rem!important;line-height:1.45!important}
  .fp-section{font-size:1.22rem!important;margin:17px 0 7px!important}
  .fp-card{padding:14px!important;border-radius:16px!important}
  .fp-chip{font-size:.76rem!important;padding:5px 8px!important}
  .fp-tree{padding:13px 14px!important;border-radius:16px!important}
  .fp-tree-line{font-size:.92rem!important;padding:7px 0!important}
  .small-muted{font-size:.78rem!important}
  .fp-side-brand{padding:7px 8px 14px!important}
  .fp-side-brand .logo{font-size:1.35rem!important}
  .fp-side-spacer{height:95px!important}
  .fp-side-footer{font-size:.85rem!important}

  [data-testid="stHorizontalBlock"]{flex-wrap:wrap!important;gap:.65rem!important}
  [data-testid="stHorizontalBlock"]>[data-testid="stColumn"]{
      flex:1 1 100%!important;
      width:100%!important;
      min-width:100%!important;
      max-width:100%!important;
  }
  [data-testid="stHorizontalBlock"]>[data-testid="stColumn"]:empty{display:none!important}
  section[data-testid="stSidebar"]{width:86vw!important;min-width:86vw!important;max-width:86vw!important}
  section[data-testid="stSidebar"] > div:first-child{padding:.6rem .5rem .8rem!important}
  section[data-testid="stSidebar"] button[kind="secondary"]{min-height:46px!important;font-size:.96rem!important}
}

/* Some mobile browsers report a wider CSS viewport; touch devices still get the
   same large hero treatment. */
@media(max-width:900px) and (pointer:coarse){
  .hero-shell{
    width:100vw!important;
    max-width:100vw!important;
    margin-left:calc(50% - 50vw)!important;
    margin-right:calc(50% - 50vw)!important;
  }
  .hero-shell img{
    width:100%!important;
    height:100%!important;
    object-fit:cover!important;
    object-position:center 47%!important;
  }
  .hero-hotspot{
    left:16%!important;top:47%!important;width:68%!important;height:18%!important;
  }
}

@media(min-width:701px) and (max-width:1200px){
  [data-testid="stHorizontalBlock"]{flex-wrap:wrap!important}
  [data-testid="stHorizontalBlock"]>[data-testid="stColumn"]{min-width:calc(50% - .5rem)!important;flex:1 1 calc(50% - .5rem)!important}
}

@media(min-width:1201px){
  .block-container{padding-left:1.2rem!important;padding-right:1.2rem!important}
}
</style>
""", unsafe_allow_html=True)

