DEFAULT_STATE = {
    "page":"home","selected_stream":None,"selected_course":None,"selected_branch":None,
    "selected_diploma":None,"selected_iti":None,"selected_specialization":None,
    "language":"English","ai_chat":[],"ai_profile":{"stage":"Class 10","stream":"Not selected","goal":"Explore options","interests":""}
}
for k,v in DEFAULT_STATE.items():
    if k not in st.session_state:
        st.session_state[k]=v

# Handle the invisible clickable hotspot route without locking the app to the query parameter.
if "page" in st.query_params:
    requested = st.query_params.get("page")
    if requested in {"journey","ai_assistant","helpdesk","home"}:
        st.session_state.page = requested
    st.query_params.clear()

T = LANG.get(st.session_state.language, LANG["English"])


def go(page):
    st.session_state.page = page
    st.rerun()

def back(page):
    st.session_state.page = page
    st.rerun()

def select_stream(name):
    if not name:
        return
    st.session_state.selected_stream=str(name)
    st.session_state.selected_course=None
    st.session_state.selected_specialization=None
    st.session_state.page="stream"
    st.rerun()

def select_course(name):
    if not name:
        st.warning("Please select a course before opening the details page.")
        return
    name=str(name).strip()
    if not name:
        return
    st.session_state.selected_course=name
    st.session_state.selected_specialization=None
    if name=="B.Tech / B.E.":
        st.session_state.page="branches"
    else:
        st.session_state.page="course_detail"
    st.rerun()

def select_branch(name):
    if not name:
        return
    st.session_state.selected_branch=str(name)
    st.session_state.page="branch"
    st.rerun()

def select_diploma(name):
    if not name:
        return
    st.session_state.selected_diploma=str(name)
    st.session_state.page="diploma_detail"
    st.rerun()

def select_iti(name):
    if not name:
        return
    st.session_state.selected_iti=str(name)
    st.session_state.page="iti_detail"
    st.rerun()

def render_back(target, key):
    st.markdown('<div class="back-wrap">', unsafe_allow_html=True)
    if st.button("←  " + T["back"].replace("← ",""), key=key, use_container_width=False):
        back(target)
    st.markdown('</div>', unsafe_allow_html=True)

# ------------------------------------------------------------
# Course profile generator — guarantees every listed course is clickable.
# ------------------------------------------------------------
def course_profile(name):
    # Guard against stale/empty Streamlit session state.
    if name is None:
        return {
            "description":"No course was selected.",
            "subjects":["Select a course from the previous page."],
            "skills":[], "projects":[], "internships":[], "careers":[], "higher":[], "branches":[]
        }
    name=str(name).strip()
    if not name:
        return {
            "description":"No course was selected.",
            "subjects":["Select a course from the previous page."],
            "skills":[], "projects":[], "internships":[], "careers":[], "higher":[], "branches":[]
        }
    if name in COURSE_PROFILE_OVERRIDES:
        d=dict(COURSE_PROFILE_OVERRIDES[name])
        d.setdefault("branches", COURSE_BRANCHES.get(name,["General / university-specific specialization"]))
        return d
    n=name.lower()
    branches=COURSE_BRANCHES.get(name)
    if not branches:
        if "b.sc" in n and "biology" in n:
            branches=["Biology","Microbiology","Biotechnology","Genetics","Research"]
        elif "b.sc" in n:
            branches=["Major Subject","Applied Science","Statistics / Analytics","Research"]
        elif n.startswith("ba") or n=="ba":
            branches=["English","History","Economics","Political Science","Psychology","Sociology"]
        elif "b.com" in n:
            branches=["Accounting","Finance","Taxation","Banking","Business Analytics"]
        elif "bba" in n:
            branches=["Finance","Marketing","HR","Operations","Business Analytics"]
        elif "b.pharm" in n or "pharm" in n:
            branches=["Pharmaceutics","Pharmacology","Pharmaceutical Chemistry","Clinical Pharmacy"]
        else:
            branches=["General / university-specific specialization"]
    if "b.com" in n:
        subjects=["Financial Accounting","Business Economics","Business Law","Taxation","Auditing","Cost Accounting"]
